/// @brief Strategy for handling animation subtiles referenced with multiple palettes.
///
/// @details
/// When decompiling animations using the scan_local_metatiles strategy, a single tile index
/// can be referenced by multiple metatile entries with different palette indices. This is valid
/// GBA behavior (the hardware selects palette per metatile entry, not per tile), but Porytiles
/// cannot represent multiple palette variants in a single RGBA layer PNG. This enum determines
/// how to handle such cases.
///
enum class AnimMultiPalSubtileResolutionStrategy {
    /// @brief Emit a formatted error and fail decompilation.
    error,
    /// @brief Emit a warning and continue decompilation using the lowest palette index.
    warning,
    /// @brief Split the animation into separate animations for each palette variant (not yet implemented).
    split
};

